#include <vector>

#include "studio.h"
#include "raymath.h"  // after raylib.h: it reuses raylib's vector types

namespace {
Mesh grass{};
Material grassMaterial{};
std::vector<Matrix> tufts;
}  // namespace

void buildGrass(studio::Rng& rng) {
  grass = GenMeshCube(0.1f, 0.4f, 0.1f);
  grassMaterial = LoadMaterialDefault();
  tufts.clear();
  for (int i = 0; i < 2000; i++)
    tufts.push_back(MatrixTranslate(rng.nextFloat(-20, 20), 0.2f, rng.nextFloat(-20, 20)));
}

void drawGrass() {
  studio::tag("grass");
  DrawMeshInstanced(grass, grassMaterial, tufts.data(), static_cast<int>(tufts.size()));
}
